import { atom, update } from 'claude-code'
import type { Register } from 'claude-code'

import { DEFAULTS } from './defaults.js'
import { BAR_HELP, barCommand, registerBar, startBar } from './bar.js'

// Generated by scripts/build-plugins.mjs from the shared code in hooks/.
const prefsAtom = atom({ plugin: 'ambient-bar', key: 'prefs' } as const, DEFAULTS, { shape: 'prefs-1' })

export const register: Register = on => {
  const deps = { themeLabel: () => '' }
  registerBar(on, deps)
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'bar', description: 'Clock, focus timer and daily quote above the prompt', argumentHint: 'focus 25 | clock 24h | quote next | on | off' })
    const stored = await $.store.get('prefs')
    await update($, prefsAtom, () => ({ ...DEFAULTS, ...(stored !== null && typeof stored === 'object' ? stored : {}) }))
    await startBar($, deps)
    return next(e)
  })
  on('command.run', { command: 'bar' }, async ($, e) => {
    const words = e.args.trim().split(/\s+/).filter(w => w !== '')
    const first = words[0]?.toLowerCase()
    const rest = words.slice(1).join(' ')
    return { text: await (first === undefined || first === 'help' ? Promise.resolve(BAR_HELP) : first === 'on' || first === 'off' ? barCommand($, 'bar', first) : barCommand($, first, words[1]?.toLowerCase())) }
  })
}
